// TH18 v1.00a Stage 6 Boss3 non-spell (st06bs.ecl.txt:315-391, helper 184-232).
// Source t0 = B:330 timerReset; slot-0 interrupt B:351 HP3000/time3000 -> BossCard3.
// Training shell: controller at (0,0) with body collision off; real boss keeps
// source hitbox/hurtbox and source position (0,128); 120-frame opening buffer.
const TIME_LIMIT: int = 3122;    // 120 buffer + 3000 source timeout + 2 frame task phase
const SOURCE_LIMIT: int = 3000;  // B:351 setInterrupt slot0 timeout
const OPENING_BUFFER: int = 120;

const TH18_TALISMAN: int = 528;  // TH18 type 11 Talisman, base radius 2.8

// B:193-195: ANIM a=1 retraction is handled by sh_dist(-4*initial speed);
// WAIT type 0x80000000 a=20; VELTIME type 0x200000 a=60, r=%L, s=-9999994
// (keep entry angle).  Linear scalar-speed ramp 1 -> target over 60 frames.
xformdef TALISMAN_MOTION(target: fx) {
    wait(20);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// B:184-232 Boss1_at.  Each async instance is a private target task, so its
// emitter slot 0 replaces the source per-call et slot B (2/0/1).
async sub at_wave(color: int, c0: angle, d0: angle, de: angle, df: angle,
                  radius: fx, axis: angle, dh: angle, ratio: fx,
                  count: int, target: fx) {
    var rank: int = global(GVAR_RANK);
    // B:196-202: Easy doubles E/F; Normal scales both by 1.2.
    var de_i: int = de as int;
    var df_i: int = df as int;
    if rank == 0 { de_i = de_i * 2; df_i = df_i * 2; }
    if rank == 1 { de_i = de_i * 6 / 5; df_i = df_i * 6 / 5; }
    var dc: angle = de_i as angle;
    var dd: angle = df_i as angle;
    // B:218-227: Easy waits 2; N/H/L wait 1.
    var step: int = 1;
    if rank == 0 { step = 2; }

    sh_reset(0);
    sh_sprite(0, TH18_TALISMAN, color); // etSprite(B,11,A)
    sh_aim(0, 0);                       // etAim(B,1): N=1 fixed direction
    sh_ring(0, 0);
    sh_count(0, 1, 1);                  // etCount(B,1,1)
    sh_speed(0, 1fx, 0fx);              // etSpeed(B,1,1), single layer
    sh_dist(0, -4fx);                   // ANIM a=1: -4 * initial speed
    sh_xform(0, TALISMAN_MOTION(target));

    for i in 0..count {
        // B:208 ins_94(M,N,D,G,H,J); phi=D, radius=G, axis=H, ratio=J.
        // Normalise to one turn like the source validRad around the loop.
        var phi: int = (d0 as int) % 65536;
        if phi > 32767 { phi = phi - 65536; }
        if phi < -32768 { phi = phi + 65536; }
        var hi: int = (axis as int) % 65536;
        if hi > 32767 { hi = hi - 65536; }
        if hi < -32768 { hi = hi + 65536; }
        var ti: int = phi - hi;
        ti = ti % 65536;
        if ti > 32767 { ti = ti - 65536; }
        if ti < -32768 { ti = ti + 65536; }
        var t: angle = ti as angle;
        var u: fx = radius * ratio * cos(t);
        var v: fx = radius * sin(t);
        var m: fx = u * cos(axis) - v * sin(axis);
        var n: fx = u * sin(axis) + v * cos(axis);
        // B:209-210: H += I and validRad(H) before the next offset.
        var ai: int = (axis + dh) as int;
        ai = ai % 65536;
        if ai > 32767 { ai = ai - 65536; }
        if ai < -32768 { ai = ai + 65536; }
        axis = ai as angle;
        sh_offset(0, m, n);      // etOffset(B,M,N)
        sh_angle(0, c0, 0deg);   // etAngle(B,C,0)
        sh_fire(0);              // etOn(B)
        // B:214-217: C += E, D += F, validRad on both.
        var ci: int = (c0 + dc) as int;
        ci = ci % 65536;
        if ci > 32767 { ci = ci - 65536; }
        if ci < -32768 { ci = ci + 65536; }
        c0 = ci as angle;
        var di: int = (d0 + dd) as int;
        di = di % 65536;
        if di > 32767 { di = di - 65536; }
        if di < -32768 { di = di + 65536; }
        d0 = di as angle;
        wait(step);
    }
}

// B:327 moveLimit(0,128,280,96): x in [-140,140], y in [80,176];
// direction-selection inner region x +-70, y 104..152.
// B:385 moveRand(100,0,0.6): speed 0.6*(1-k/100), k=1..100.
// Shared slots: self_int(0)=next step count, self_fx(0/1)=logical unit vector.
sub move_arm(duration: int, speed0: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < duration { speed = speed0 * ((duration - k) as fx) / (duration as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// The main task arms k=1 at the moveRand call; this task continues k=2..duration,
// so the first source movement tick is not delayed by the async first-run frame.
async sub move_continue(duration: int, speed0: fx) {
    loop {
        move_arm(duration, speed0);
        if self_int(0) >= duration { return; }
        wait(1);
    }
}

sub card_move_rand() {
    // B:385 412 moveRand(100,0,0.6): R = pi*U -> BAM r; same branch logic as movement.md.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_arm(100, 0.6fx);
}

// B:315-391 Boss3.  Source t0 = timerReset B:330; B:353 wait90 and B:355
// wait80 are the 170-frame prelude.  Two streams at B:368/378, plus a third
// on Hard/Lunatic at B:380/382.  Cycle: wait600, moveRand, wait60.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(90); // B:353
    wait(80); // B:355
    var rank: int = global(GVAR_RANK);
    // Last pushed value at B:359-367 / B:369-377; L never inherits H.
    var l1: fx = 3.5fx;
    if rank == 2 { l1 = 3.7fx; }
    if rank == 3 { l1 = 4.1fx; }
    var l2: fx = 3.0fx;
    if rank == 2 { l2 = 3.3fx; }
    if rank == 3 { l2 = 3.5fx; }
    loop {
        spawn at_wave(10, 90deg, 0deg, 6deg, 7.1deg, 64fx, -90deg,
                      2deg, 0.5fx, 600, l1); // B:368
        spawn at_wave(8, 180deg, -90deg, 6deg, 3.6deg, 64fx, 90deg,
                      -3deg, 0.5fx, 600, l2); // B:378
        if rank >= 2 {
            spawn at_wave(11, 0deg, -90deg, 6deg, 5.6deg, 64fx, 90deg,
                          -3deg, 0.5fx, 600, 3.0fx); // B:380/382
        }
        wait(600);        // B:384
        card_move_rand(); // B:385
        spawn move_continue(100, 0.6fx);
        wait(60);         // B:386
    }
}

async sub boss_main() {
    // Source B:33-35: hurtbox 40x40 -> 20, hitbox 48x48 -> 24; B:8-40 entry
    // position (0,128).  Invulnerability keeps the window on the source timeout.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Extra training-only phase controller at (0,0); it never carries source judgement.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 19000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
